  worksIn3d: ["works in the 3D view", "funciona en la vista 3D", "funktioniert in der 3D-Ansicht", "fonctionne dans la vue 3D", "funziona nella vista 3D", "3D ビューで使用可能", "在 3D 视图中可用"],
  deleteObjectHelp: ["Delete what is selected (a corner, if a corner is selected).", "Elimina lo seleccionado (una esquina, si hay una esquina seleccionada).", "Auswahl löschen (eine Ecke, wenn eine Ecke gewählt ist).", "Supprime la sélection (un coin, si un coin est sélectionné).", "Elimina la selezione (un angolo, se è selezionato un angolo).", "選択中のものを削除します（角が選択中ならその角）。", "删除所选内容（若选中角点则删除该角点）。"],
  turnLeft: ["Turn left 15°", "Girar a la izquierda 15°", "15° nach links drehen", "Tourner à gauche de 15°", "Ruota a sinistra di 15°", "左へ 15° 回転", "向左转 15°"],
  turnLeftHelp: ["Turn the selected object 15° anticlockwise about the vertical axis.", "Gira el objeto seleccionado 15° en sentido antihorario sobre el eje vertical.", "Ausgewähltes Objekt um 15° gegen den Uhrzeigersinn um die Hochachse drehen.", "Fait tourner l'objet sélectionné de 15° dans le sens antihoraire autour de l'axe vertical.", "Ruota l'oggetto selezionato di 15° in senso antiorario attorno all'asse verticale.", "選択物を垂直軸まわりに反時計回りへ 15° 回します。", "将所选物体绕垂直轴逆时针旋转 15°。"],
  turnRight: ["Turn right 15°", "Girar a la derecha 15°", "15° nach rechts drehen", "Tourner à droite de 15°", "Ruota a destra di 15°", "右へ 15° 回転", "向右转 15°"],
  turnRightHelp: ["Turn the selected object 15° clockwise about the vertical axis.", "Gira el objeto seleccionado 15° en sentido horario sobre el eje vertical.", "Ausgewähltes Objekt um 15° im Uhrzeigersinn um die Hochachse drehen.", "Fait tourner l'objet sélectionné de 15° dans le sens horaire autour de l'axe vertical.", "Ruota l'oggetto selezionato di 15° in senso orario attorno all'asse verticale.", "選択物を垂直軸まわりに時計回りへ 15° 回します。", "将所选物体绕垂直轴顺时针旋转 15°。"],
  tiltForward: ["Tilt forward 15° (about X)", "Inclinar hacia delante 15° (eje X)", "15° nach vorn kippen (um X)", "Incliner vers l'avant de 15° (axe X)", "Inclina in avanti di 15° (asse X)", "前へ 15° 傾ける（X 軸）", "向前倾斜 15°（X 轴）"],
  tiltForwardHelp: ["Tip the selected object about the east-west axis (X), forward. A camera or radar looks 15° more downward.", "Inclina el objeto seleccionado sobre el eje este-oeste (X), hacia delante. Una cámara o un radar mira 15° más hacia abajo.", "Ausgewähltes Objekt um die Ost-West-Achse (X) nach vorn kippen. Kamera oder Radar blickt 15° weiter nach unten.", "Incline l'objet sélectionné autour de l'axe est-ouest (X), vers l'avant. Une caméra ou un radar regarde 15° plus bas.", "Inclina l'oggetto selezionato attorno all'asse est-ovest (X), in avanti. Una telecamera o un radar guarda 15° più in basso.", "選択物を東西軸（X）まわりに前へ傾けます。カメラ／レーダーは 15° 下向きになります。", "将所选物体绕东西轴（X）向前倾斜；摄像头或雷达多向下看 15°。"],
  tiltBack: ["Tilt back 15° (about X)", "Inclinar hacia atrás 15° (eje X)", "15° nach hinten kippen (um X)", "Incliner vers l'arrière de 15° (axe X)", "Inclina indietro di 15° (asse X)", "後ろへ 15° 傾ける（X 軸）", "向后倾斜 15°（X 轴）"],
  tiltBackHelp: ["Tip the selected object about the east-west axis (X), backward. A camera or radar looks 15° more upward.", "Inclina el objeto seleccionado sobre el eje este-oeste (X), hacia atrás. Una cámara o un radar mira 15° más hacia arriba.", "Ausgewähltes Objekt um die Ost-West-Achse (X) nach hinten kippen. Kamera oder Radar blickt 15° weiter nach oben.", "Incline l'objet sélectionné autour de l'axe est-ouest (X), vers l'arrière. Une caméra ou un radar regarde 15° plus haut.", "Inclina l'oggetto selezionato attorno all'asse est-ovest (X), indietro. Una telecamera o un radar guarda 15° più in alto.", "選択物を東西軸（X）まわりに後ろへ傾けます。カメラ／レーダーは 15° 上向きになります。", "将所选物体绕东西轴（X）向后倾斜；摄像头或雷达多向上看 15°。"],
  tiltLeft: ["Tilt left 15° (about Z)", "Inclinar a la izquierda 15° (eje Z)", "15° nach links kippen (um Z)", "Incliner à gauche de 15° (axe Z)", "Inclina a sinistra di 15° (asse Z)", "左へ 15° 傾ける（Z 軸）", "向左倾斜 15°（Z 轴）"],
  tiltLeftHelp: ["Tip the selected object about the north-south axis (Z), to the left.", "Inclina el objeto seleccionado sobre el eje norte-sur (Z), hacia la izquierda.", "Ausgewähltes Objekt um die Nord-Süd-Achse (Z) nach links kippen.", "Incline l'objet sélectionné autour de l'axe nord-sud (Z), vers la gauche.", "Inclina l'oggetto selezionato attorno all'asse nord-sud (Z), a sinistra.", "選択物を南北軸（Z）まわりに左へ傾けます。", "将所选物体绕南北轴（Z）向左倾斜。"],
  tiltRight: ["Tilt right 15° (about Z)", "Inclinar a la derecha 15° (eje Z)", "15° nach rechts kippen (um Z)", "Incliner à droite de 15° (axe Z)", "Inclina a destra di 15° (asse Z)", "右へ 15° 傾ける（Z 軸）", "向右倾斜 15°（Z 轴）"],
  tiltRightHelp: ["Tip the selected object about the north-south axis (Z), to the right.", "Inclina el objeto seleccionado sobre el eje norte-sur (Z), hacia la derecha.", "Ausgewähltes Objekt um die Nord-Süd-Achse (Z) nach rechts kippen.", "Incline l'objet sélectionné autour de l'axe nord-sud (Z), vers la droite.", "Inclina l'oggetto selezionato attorno all'asse nord-sud (Z), a destra.", "選択物を南北軸（Z）まわりに右へ傾けます。", "将所选物体绕南北轴（Z）向右倾斜。"],
  cannotTurn: ["That cannot be turned that way.", "Eso no se puede girar en ese eje.", "Das lässt sich so nicht drehen.", "Cela ne peut pas tourner ainsi.", "Non si può ruotare in quel modo.", "その向きには回せません。", "无法沿该轴旋转。"],
  turnAboutVertical: ["Turn (vertical axis)", "Giro (eje vertical)", "Drehung (Hochachse)", "Rotation (axe vertical)", "Rotazione (asse verticale)", "回転（垂直軸）", "旋转（垂直轴）"],
  tiltAboutX: ["Tilt about X (east-west)", "Inclinación en X (este-oeste)", "Neigung um X (Ost-West)", "Inclinaison sur X (est-ouest)", "Inclinazione su X (est-ovest)", "X 軸の傾き（東西）", "绕 X 倾斜（东西）"],
  tiltAboutZ: ["Tilt about Z (north-south)", "Inclinación en Z (norte-sur)", "Neigung um Z (Nord-Süd)", "Inclinaison sur Z (nord-sud)", "Inclinazione su Z (nord-sud)", "Z 軸の傾き（南北）", "绕 Z 倾斜（南北）"],
